import React, { useState } from 'react';
import { skillsData } from '../data/skillsData';

function Skills() {
  const [activeCategory, setActiveCategory] = useState('frontend');

  const SkillBar = ({ skill, index }) => (
    <div className="card-hover group rounded-xl p-6 animate-fade-in-up" style={{ animationDelay: `${index * 0.1}s` }}>
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 bg-gradient-to-r from-[#6699CC]/20 to-[#58A6FF]/20 rounded-lg flex items-center justify-center backdrop-blur-sm border border-[#6699CC]/30 group-hover:border-[#6699CC]/60 transition-colors duration-300">
            <span className="text-xl group-hover:scale-110 transition-transform duration-300">{skill.icon}</span>
          </div>
          <h4 className="text-lg font-semibold text-white group-hover:text-gradient transition-colors duration-300">{skill.name}</h4>
        </div>
        <span className="text-[#6699CC] font-bold text-lg animate-glow">{skill.level}%</span>
      </div>

      <div className="w-full bg-gray-700/50 rounded-full h-3 mb-3 overflow-hidden backdrop-blur-sm">
        <div 
          className="bg-gradient-to-r from-[#6699CC] via-[#58A6FF] to-[#BC8CFF] h-3 rounded-full transition-all duration-1000 ease-out relative overflow-hidden"
          style={{ width: `${skill.level}%` }}
        >
          <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent transform -skew-x-12 animate-shimmer"></div>
        </div>
      </div>

      <p className="text-gray-400 text-sm leading-relaxed">{skill.experience}</p>
    </div>
  );

  return (
    <section id="skills" className="py-20 px-6 sm:px-8 lg:px-12 relative overflow-hidden">
      {/* Background Effects */}
      <div className="absolute inset-0 opacity-20">
        <div className="absolute top-0 left-0 w-96 h-96 bg-gradient-to-r from-green-500/20 to-transparent rounded-full blur-3xl animate-float"></div>
        <div className="absolute bottom-0 right-0 w-80 h-80 bg-gradient-to-l from-blue-500/20 to-transparent rounded-full blur-3xl animate-float" style={{ animationDelay: '1s' }}></div>
      </div>

      <div className="max-w-7xl mx-auto relative z-10">
        {/* Enhanced Section Header */}
        <div className="text-center mb-16 animate-fade-in-up">
          <h2 className="text-4xl sm:text-5xl md:text-6xl font-bold text-white mb-6">
            My <span className="text-gradient animate-glow">Skills</span>
          </h2>
          <div className="w-24 h-1 bg-gradient-to-r from-[#6699CC] to-[#58A6FF] mx-auto rounded-full mb-8 shadow-elegant"></div>
          <p className="text-gray-300 text-xl max-w-3xl mx-auto leading-relaxed">
            A comprehensive overview of my technical expertise and the tools I use to bring ideas to life
          </p>
        </div>

        {/* Enhanced Category Tabs */}
        <div className="flex flex-wrap justify-center gap-4 mb-12 animate-fade-in-up" style={{ animationDelay: '0.2s' }}>
          {Object.entries(skillsData).map(([key, category], index) => (
            <button
              key={key}
              onClick={() => setActiveCategory(key)}
              className={`group relative px-6 py-3 rounded-xl font-medium transition-all duration-300 flex items-center space-x-2 transform hover:scale-105 ${
                activeCategory === key
                  ? 'bg-gradient-to-r from-[#6699CC] to-[#58A6FF] text-white shadow-elegant'
                  : 'bg-gray-800/50 backdrop-blur-sm text-gray-300 hover:bg-gray-700/50 hover:text-white border border-gray-600/30 hover:border-[#6699CC]/50'
              }`}
              style={{ animationDelay: `${index * 0.1}s` }}
            >
              {activeCategory === key && (
                <div className="absolute inset-0 bg-gradient-to-r from-[#6699CC]/20 to-[#58A6FF]/20 rounded-xl animate-pulse-subtle"></div>
              )}
              <span className="relative z-10 text-xl">{category.icon}</span>
              <span className="relative z-10">{category.title}</span>
            </button>
          ))}
        </div>

        {/* Enhanced Skills Grid */}
        <div className="grid-modern animate-fade-in-up" style={{ animationDelay: '0.4s' }}>
          {skillsData[activeCategory]?.skills.map((skill, index) => (
            <SkillBar key={skill.name} skill={skill} index={index} />
          ))}
        </div>
      </div>
    </section>
  );
}

export default Skills;
